output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles, i.e. narrow passages flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_entering_single_file_with_cart",
    "text": "A shopper must not move from an open area into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "cart_interaction_at_mouth_means_parking",
    "text": "When a shopper with a cart interacts at the mouth of a single-file shelf aisle, the interaction must be a cart-parking action.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "singleFileAisleMouth": {
          "and": [
            "wideOpenAisle",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "mouthCartInteraction": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartDropAtMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "mouthCartInteraction",
      "discharge": "cartDropAtMouth"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart to enter a narrow shelf aisle, the shopper is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "wideOpenParkingZone": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "wideOpenParkingZone",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrieve": {
          "pre": {
            "and": [
              "wideOpenParkingZone",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartRetrieve"
    }
  },
  {
    "id": "return_to_mouth_after_narrow_item",
    "text": "After interacting with an item inside a single-file shelf aisle, the shopper must return cartless to a wide aisle mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideOpenAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "narrowAisleItemInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "exitNarrowAisleCartless": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "wideOpenAisle",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "narrowAisleItemInteraction",
      "discharge": "exitNarrowAisleCartless"
    }
  },
  {
    "id": "only_park_carts_in_wide_open_zones",
    "text": "A shopper may set down a cart only in a wide open aisle zone, not beside shelf faces or inside narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingZone": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "cartParkingZone"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_movement_past_open_shelf_faces",
    "text": "A shopper without a cart must not move along a wide shelf-facing aisle, although cartless movement inside narrow shelf aisles is allowed.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideShelfFacingAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "MOVE",
          "wideShelfFacingAisle"
        ]
      }
    }
  },
  {
    "id": "open_shelf_interactions_require_cart",
    "text": "Items reachable from open shelf-facing aisles should be collected while keeping the cart, unlike items inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
